# Receipt /private/var/db/nord2-stock/wallpaper1.json + backup of the original plist. Idempotent; WALLPAPER1_REFUSED = no change.
import os, json, glob, hashlib, plistlib
R='/work/root'
FF='/System/Library/FeatureFlags/Domain/ExtensionKit.plist'; FLAG='enforce_xpc_cache_code_signing'
XC='/System/Library/xpc/extensions.plist'; EPD='/System/Library/ExtensionKit/ExtensionPoints'; NEW=EPD+'/nord2-xpc-extension-points.appexpt'
D='/private/var/db/nord2-stock'; REC=D+'/wallpaper1.json'; BK=D+'/wallpaper1'; BKFF=BK+'/ExtensionKit.plist'
LSG='/private/var/mobile/Containers/Data/InternalDaemon/*/Library/Caches/*LaunchServices-*.csstore'
NEED=('com.apple.posterkit.provider','com.apple.widgetkit-extension')
sha=lambda b: hashlib.sha256(b).hexdigest(); rd=lambda p: open(R+p,'rb').read()
def put(path, data, mode, uid, gid):
    tmp=R+path+'.nord2tmp'
    if os.path.lexists(tmp): os.remove(tmp)
    with open(tmp,'xb') as f: f.write(data); f.flush(); os.fsync(f.fileno())
    os.chmod(tmp,mode); os.chown(tmp,uid,gid); os.replace(tmp,R+path)
    assert rd(path)==data
def lsaside(tag):
    moved=[]
    for f in glob.glob(R+LSG):
