        cache=plistlib.loads(rd(XC))
        if not isinstance(cache,dict) or any(n not in cache for n in NEED): return ('%s lacks %s'%(XC,NEED),)+(None,)*5
        if not os.path.isdir(R+EPD): return (EPD+' missing',)+(None,)*5
        have=set()
        for f in sorted(glob.glob(R+EPD+'/*.appexpt')):
            if f!=R+NEW: have|=set(plistlib.load(open(f,'rb')))
        out={}
        for ident in sorted(cache):
            v=cache[ident]
            fws=sorted(k for k in v if k.startswith('/System/') and isinstance(v[k],dict)) if isinstance(v,dict) else []
            if ident not in have and fws: out[ident]=v[fws[0]]
        if any(n not in out for n in NEED): return ('poster/widget points already defined or unreadable',)+(None,)*5
        return None,raw,ff,plistlib.dumps(out,fmt=plistlib.FMT_BINARY,sort_keys=True),len(out),sorted(have)
    except Exception as e: return ('unreadable input: %r'%(e,),)+(None,)*5
err,raw,ff,appexpt,npts,have=state()
rec=json.load(open(R+REC)) if os.path.exists(R+REC) else None
if err: print('WALLPAPER1_REFUSED', err)
elif not UNDO:
    fst=os.stat(R+FF); fmt=plistlib.FMT_BINARY if raw[:6]==b'bplist' else plistlib.FMT_XML
    if rec is None and (ff[FLAG]['Enabled'] is not True or os.path.lexists(R+NEW) or os.path.lexists(R+BK)):
        print('WALLPAPER1_REFUSED no receipt but flag=%s appexpt=%s backup=%s'%(ff[FLAG]['Enabled'],os.path.lexists(R+NEW),os.path.lexists(R+BK)))
    elif rec is not None and (not os.path.exists(R+BKFF) or sha(rd(BKFF))!=rec['ff_sha_before'] or sha(raw) not in (rec['ff_sha_before'],rec.get('ff_sha_after'))):
        print('WALLPAPER1_REFUSED receipt does not match the files on disk')
    else:
        changed=False
        if rec is None:
            os.makedirs(R+D,exist_ok=True); os.chmod(R+D,0o755); os.makedirs(R+BK); os.chmod(R+BK,0o755)
            put(BKFF,raw,fst.st_mode&0o7777,fst.st_uid,fst.st_gid)
            rec={'by':'payload-wallpaper1','ff':FF,'flag':FLAG,'ff_sha_before':sha(raw),'ff_backup':BKFF,'appexpt':NEW}
            json.dump(rec,open(R+REC,'w'),indent=1)
        if ff[FLAG]['Enabled'] is not False:
            ff[FLAG]=dict(ff[FLAG],Enabled=False); out=plistlib.dumps(ff,fmt=fmt,sort_keys=False)
            put(FF,out,fst.st_mode&0o7777,fst.st_uid,fst.st_gid); assert plistlib.loads(rd(FF))[FLAG]['Enabled'] is False
            rec['ff_sha_after']=sha(out); json.dump(rec,open(R+REC,'w'),indent=1); changed=True
        if not os.path.exists(R+NEW) or rd(NEW)!=appexpt:
            like=sorted(f for f in glob.glob(R+EPD+'/*.appexpt') if f!=R+NEW); st=os.stat(like[0]) if like else fst
            put(NEW,appexpt,st.st_mode&0o7777,st.st_uid,st.st_gid); changed=True
        chk=plistlib.loads(rd(NEW)); assert all(n in chk and 'NSExtension' in chk[n] for n in NEED)
