            changed,plistlib.loads(rd(FF))[FLAG]['Enabled'],len(chk),len(have),NEED[0] in chk,NEED[1] in chk,ls))
else:
    if rec is None: print('WALLPAPER1_UNDO nothing to undo')
    elif not os.path.exists(R+BKFF) or sha(rd(BKFF))!=rec['ff_sha_before'] or sha(raw) not in (rec['ff_sha_before'],rec.get('ff_sha_after')):
